void WebServer::handleConfig(uint8_t sn){
    if(serveFile(sn,"/config.html","text/html")) return;
    // Embedded fallback — send from .rodata array (no stack allocation)
    {
        char hdr[192];
        int hl=std::snprintf(hdr,sizeof(hdr),
            "HTTP/1.1 200 OK\r\nContent-Type: text/html; charset=UTF-8\r\n"
            "Content-Length: %lu\r\nAccess-Control-Allow-Origin: *\r\n"
            "Connection: close\r\n\r\n",
            (unsigned long)s_config_html_len);
        w5500_send(sn,(uint8_t*)hdr,(uint16_t)hl);
        const uint8_t* p = s_config_html;
        uint32_t rem = s_config_html_len;
        while(rem > 0){
            uint16_t n = (rem > 512u) ? 512u : (uint16_t)rem;
            w5500_send(sn, p, n);
            p   += n;
            rem -= n;
            IWDG->KR = 0xAAAA;
        }
    }
}

