// ── POST /api/test_send  /  GET /api/test_result ──────────────────────────────
// forward declaration — defined later in this file
static bool getQueryParam(const char* qs, const char* key, char* out, size_t outSz);

void WebServer::handleApiTestSend(uint8_t sn, const char* queryStr){
    char valStr[32]{};
    if(queryStr && queryStr[0]){
        /* inline mini-parser: find "value=NNN" in query string */
        const char* p = std::strstr(queryStr, "value=");
        if(p){
            p += 6; /* skip "value=" */
            size_t i = 0;
            while(*p && *p != '&' && i < sizeof(valStr)-1)
                valStr[i++] = *p++;
            valStr[i] = '\0';
        }
    }
    if(valStr[0]){
        float v = (float)std::atof(valStr);
        if(m_app) m_app->setTestValue(v);
    }
    if(m_app) m_app->triggerTestSend();
    const char* r="{\"ok\":true}";
    sendResponse(sn,200,"application/json",r,(uint16_t)std::strlen(r));
}
void WebServer::handleApiTestResult(uint8_t sn){
    char state[16]{},channel[16]{}; int httpCode=0; uint32_t elapsed=0;
    if(m_app) m_app->getTestResult(state,channel,&httpCode,&elapsed);
    else std::strncpy(state,"idle",sizeof(state)-1);
    char buf[256];
    int len=std::snprintf(buf,sizeof(buf),
        "{\"status\":\"%s\",\"channel\":\"%s\","
        "\"http_code\":%d,\"elapsed_ms\":%lu}",
        state,channel,httpCode,(unsigned long)elapsed);
    sendResponse(sn,200,"application/json",buf,(uint16_t)len);
}
void WebServer::handleApiTestPayload(uint8_t sn){
    /* Use m_respBuf (8KB, heap-resident) instead of static 512B buffer —
     * ocean-monitor JSON array can be >512 bytes for multiple sensors. */
    int plen = m_app ? m_app->getTestPayload(m_respBuf, RESP_BUF_SIZE) : 0;
    if(plen<=0){
        const char* e="{}";
        sendResponse(sn,200,"application/json",e,(uint16_t)std::strlen(e));
        return;
    }
    sendResponse(sn,200,"application/json",m_respBuf,(uint16_t)plen);
}

// ── GET /api/logs ─────────────────────────────────────────────────────────────
void WebServer::handleApiLogs(uint8_t sn,const char* queryStr){
    uint32_t offset=0; uint16_t count=50;
    if(queryStr&&queryStr[0]){
        const char* p=std::strstr(queryStr,"offset=");
        if(p) offset=(uint32_t)std::atoi(p+7);
        p=std::strstr(queryStr,"count=");
        if(p){count=(uint16_t)std::atoi(p+6);if(count>100)count=100;}
    }
    CircularLogBuffer& log=CircularLogBuffer::instance();
    uint16_t total=log.getCount();
    /* Use m_respBuf (heap-resident member) instead of 6 KB stack array */
    char* resp=m_respBuf; const int rsz=RESP_BUF_SIZE; int pos=0;
    pos+=std::snprintf(resp+pos,rsz-pos,
        "{\"total\":%lu,\"lines\":[",(unsigned long)log.getTotal());
    bool first=true;
    char line[CircularLogBuffer::LINE_SIZE];
    for(uint16_t i=0;i<count&&(offset+i)<total;++i){
        if(!log.getLine((uint16_t)(offset+i),line,sizeof(line))) continue;
        if(!first&&pos<rsz-10) resp[pos++]=',';
        if(pos<rsz-(int)CircularLogBuffer::LINE_SIZE-4){
            resp[pos++]='"';
            for(char* c=line;*c&&pos<rsz-4;++c){
                if(*c=='"') resp[pos++]='\\';
                resp[pos++]=*c;
            }
            resp[pos++]='"'; first=false;
        }
    }
    if(pos<rsz-2){resp[pos++]=']';resp[pos++]='}';resp[pos]='\0';}
    sendResponse(sn,200,"application/json",resp,(uint16_t)pos);
}
void WebServer::handleApiLogsExport(uint8_t sn)
{
    CircularLogBuffer& log = CircularLogBuffer::instance();
    uint16_t total = log.getCount();

    // Отправляем заголовок вручную (размер заранее не известен)
    char hdr[256];
    int hl = std::snprintf(hdr, sizeof(hdr),
        "HTTP/1.1 200 OK\r\nContent-Type: text/plain; charset=UTF-8\r\n"
        "Content-Disposition: attachment; filename=\"monset.log\"\r\n"
        "Access-Control-Allow-Origin: *\r\nTransfer-Encoding: chunked\r\n"
        "Connection: close\r\n\r\n");
    send(sn, (uint8_t*)hdr, (uint16_t)hl);

    char line[CircularLogBuffer::LINE_SIZE];
    for (uint16_t i = 0; i < total; i++) {
        if (log.getLine(i, line, sizeof(line))) {
            // chunked HTTP: размер строки в hex
            char chunk_hdr[12];
            int chl = std::snprintf(chunk_hdr, sizeof(chunk_hdr),
                "%X\r\n", (unsigned)std::strlen(line));
            send(sn, (uint8_t*)chunk_hdr, (uint16_t)chl);
            send(sn, (uint8_t*)line, (uint16_t)std::strlen(line));
            send(sn, (uint8_t*)"\r\n", 2);
            IWDG->KR = 0xAAAA;
        }
    }
    // Завершающий chunk
    send(sn, (uint8_t*)"0\r\n\r\n", 5);
}
void WebServer::handleApiLogsClear(uint8_t sn){
    CircularLogBuffer::instance().clear();
    const char* r="{\"ok\":true}";
    sendResponse(sn,200,"application/json",r,(uint16_t)std::strlen(r));
}

// ── GET /api/backup/download ───────────────────────────────────────────────
void WebServer::handleApiBackupDownload(uint8_t sn){
    if(!m_sdOk||!m_backup){
        const char* e="{\"error\":\"SD unavailable\"}";
        sendResponse(sn,503,"application/json",e,(uint16_t)std::strlen(e));
        return;
    }
    if(!m_backup->exists()){
        const char* e="{\"error\":\"no backup file\"}";
        sendResponse(sn,404,"application/json",e,(uint16_t)std::strlen(e));
        return;
    }
    char fpath[64];
    m_backup->getFilePath(fpath,sizeof(fpath));
    FIL fil;
    if(f_open(&fil,fpath,FA_READ)!=FR_OK){
        const char* e="{\"error\":\"f_open failed\"}";
        sendResponse(sn,500,"application/json",e,(uint16_t)std::strlen(e));
        return;
    }
    char hdr[192];
    int hl=std::snprintf(hdr,sizeof(hdr),
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: application/json\r\n"
        "Content-Disposition: attachment; filename=\"backup.jsn\"\r\n"
        "Access-Control-Allow-Origin: *\r\n"
        "Connection: close\r\n\r\n");
    w5500_send(sn,(uint8_t*)hdr,(uint16_t)hl);
    char line[256];
    while(f_gets(line,sizeof(line),&fil)){
        uint16_t ln=(uint16_t)std::strlen(line);
        if(ln>0) w5500_send(sn,(uint8_t*)line,ln);
        IWDG->KR=0xAAAA;
    }
    f_close(&fil);
}

// ── POST /api/settime ─────────────────────────────────────────────────────────
void WebServer::handleApiSetTime(uint8_t sn, const char* body) {
    if (!body || std::strlen(body) < 2) {
        const char* r = "{\"ok\":false,\"error\":\"empty body\"}";
        sendResponse(sn, 400, "application/json", r, (uint16_t)std::strlen(r)); return;
    }
    if (!m_rtc) {
        const char* r = "{\"ok\":false,\"error\":\"RTC not bound\"}";
        sendResponse(sn, 503, "application/json", r, (uint16_t)std::strlen(r)); return;
    }
    DateTime dt{};
    auto getI = [&](const char* key) -> int {
        const char* p = std::strstr(body, key);
        if (!p) return 0;
        p += std::strlen(key);
        while (*p == ':' || *p == ' ') p++;
        return (int)std::strtol(p, nullptr, 10);
    };
    int yr  = getI("\"year\"");
    dt.year    = (uint8_t)((yr >= 2000) ? (yr - 2000) : (yr > 0 ? yr : 25));
    dt.month   = (uint8_t)getI("\"month\"");
    dt.date    = (uint8_t)getI("\"day\"");
    dt.hours   = (uint8_t)getI("\"hour\"");
    dt.minutes = (uint8_t)getI("\"minute\"");
    dt.seconds = (uint8_t)getI("\"second\"");
    if (dt.month < 1 || dt.month > 12 || dt.date < 1 || dt.date > 31 ||
        dt.hours > 23 || dt.minutes > 59 || dt.seconds > 59) {
        const char* r = "{\"ok\":false,\"error\":\"invalid datetime\"}";
        sendResponse(sn, 400, "application/json", r, (uint16_t)std::strlen(r)); return;
    }
    bool ok = m_rtc->setTimeAutoDOW(dt);
    if (ok) {
        char resp[80];
        std::snprintf(resp, sizeof(resp),
            "{\"ok\":true,\"set\":\"20%02u-%02u-%02uT%02u:%02u:%02u\"}",
            (unsigned)dt.year,(unsigned)dt.month,(unsigned)dt.date,
            (unsigned)dt.hours,(unsigned)dt.minutes,(unsigned)dt.seconds);
        sendResponse(sn, 200, "application/json", resp, (uint16_t)std::strlen(resp));
    } else {
        const char* r = "{\"ok\":false,\"error\":\"DS3231 write failed\"}";
        sendResponse(sn, 500, "application/json", r, (uint16_t)std::strlen(r));
    }
}

// ── POST /config ──────────────────────────────────────────────────────────────
void WebServer::handlePostConfig(uint8_t sn,const char* body){
    if(!body||std::strlen(body)<2){
        const char* r="{\"error\":\"empty body\"}";
        sendResponse(sn,400,"application/json",r,(uint16_t)std::strlen(r)); return;
    }

    // Parse into backup object first; commit only after successful parse.
    // This avoids rollback copies around save path and keeps mutation localized.
    RuntimeConfig& tmp = CfgBackup();
    if(tmp.loadFromJson(body,std::strlen(body))){
        bool sdSaved = tmp.saveToSd(RUNTIME_CONFIG_FILENAME);
        if (sdSaved) m_sdOk = true;

        Cfg() = tmp;

        /* Пересоздать каналы по новой конфигурации — без перезагрузки */
        if (m_app) m_app->reinitChannelManager();

        /* Статические JSON-ответы — без snprintf/буфера, нет риска переполнения */
        static const char RESP_SD[]  = "{\"status\":\"ok\",\"saved_to_sd\":true}";
        static const char RESP_RAM[] = "{\"status\":\"ok_ram\",\"saved_to_sd\":false}";
        const char* resp = sdSaved ? RESP_SD : RESP_RAM;
        sendResponse(sn, 200, "application/json", resp, (uint16_t)std::strlen(resp));
        DBG.info("WebServer: config updated via tmp cfg, sd_saved=%d", (int)sdSaved);
    }else{
        const char* r="{\"error\":\"JSON parse failed\"}";
        sendResponse(sn,400,"application/json",r,(uint16_t)std::strlen(r));
    }
}

// ── Router ────────────────────────────────────────────────────────────────────

// ── GET /api/sd-test — пошаговая диагностика записи на SD ────────────────────
// Выполняет каждый шаг saveToSd() отдельно и возвращает FRESULT каждого шага.
// Использовать: curl http://<ip>/api/sd-test  или открыть в браузере.
void WebServer::handleApiSdTest(uint8_t sn) {
    static const char* TEST_FILE  = "0:/sd_test_write.tmp";
    static const char* TEST_FILE2 = "0:/sd_test_write.json";
    static const char* TEST_DATA  = "{\"sd_test\":true}";

    // --- шаг 1: stat — существование тестового файла ---
    FILINFO fno1;
    FRESULT fr1 = f_stat(TEST_FILE, &fno1);

    // --- шаг 2: chmod — не используется (_USE_CHMOD=0), пропускаем ---
    FRESULT fr2 = FR_OK;  // f_chmod недоступен в этой конфигурации FatFS

    // --- шаг 3: unlink ---
    FRESULT fr3 = f_unlink(TEST_FILE);

    // --- шаг 4: f_open FA_CREATE_ALWAYS | FA_WRITE ---
    FIL f4;
    FRESULT fr4 = f_open(&f4, TEST_FILE, FA_CREATE_ALWAYS | FA_WRITE);

    // --- шаг 5: f_write ---
    UINT bw = 0;
    FRESULT fr5 = FR_INT_ERR;
    if (fr4 == FR_OK) {
        fr5 = f_write(&f4, TEST_DATA, (UINT)std::strlen(TEST_DATA), &bw);
        f_close(&f4);
    }

    // --- шаг 6: f_rename -> .json ---
    FRESULT fr6 = FR_INT_ERR;
    if (fr5 == FR_OK && bw > 0) {
        f_unlink(TEST_FILE2);
        fr6 = f_rename(TEST_FILE, TEST_FILE2);
    }

    // --- шаг 7: f_unlink .json (cleanup) ---
    FRESULT fr7 = f_unlink(TEST_FILE2);

    // --- stat реального config файла ---
    FILINFO cfgInfo;
    FRESULT frCfg = f_stat(RUNTIME_CONFIG_FILENAME, &cfgInfo);
    char cfgTmpName[64];
    std::snprintf(cfgTmpName, sizeof(cfgTmpName), "%s.tmp", RUNTIME_CONFIG_FILENAME);
    FILINFO tmpInfo;
    FRESULT frTmp = f_stat(cfgTmpName, &tmpInfo);

    char resp[512];
    std::snprintf(resp, sizeof(resp),
        "{"
        "\"step1_stat_tmp\":%d,"
        "\"step2_chmod\":%d,"
        "\"step3_unlink\":%d,"
        "\"step4_open\":%d,"
        "\"step5_write\":%d,\"bytes_written\":%u,"
        "\"step6_rename\":%d,"
        "\"step7_cleanup\":%d,"
        "\"cfg_stat\":%d,"
        "\"cfg_tmp_stat\":%d,"
        "\"result\":\"%s\""
        "}",
        (int)fr1, (int)fr2, (int)fr3, (int)fr4,
        (int)fr5, (unsigned)bw,
        (int)fr6, (int)fr7,
        (int)frCfg, (int)frTmp,
        (fr4 == FR_OK && fr5 == FR_OK && fr6 == FR_OK) ? "PASS" : "FAIL"
    );

    sendResponse(sn, 200, "application/json", resp, (uint16_t)std::strlen(resp));
}

void WebServer::handleRequest(uint8_t sn,const char* request,uint16_t reqLen){
    if(!checkAuth(request)){send401(sn);return;}
    if(m_activityCb) m_activityCb(m_activityCtx);
    if(m_app) m_app->notifyWebActivity();

    char method[8]{},path[64]{};
    std::sscanf(request,"%7s %63s",method,path);
    DBG.info("WebServer: %s %s",method,path);

    char cleanPath[64]; std::strncpy(cleanPath,path,sizeof(cleanPath)-1);
    char* qs=std::strchr(cleanPath,'?'); if(qs)*qs='\0';
    const char* queryStr=qs?(std::strchr(path,'?')+1):"";

    if(std::strcmp(method,"GET")==0){
        if(std::strcmp(cleanPath,"/")==0||
           std::strcmp(cleanPath,"/index.html")==0)      handleIndex(sn);
        else if(std::strcmp(cleanPath,"/config")==0||
                std::strcmp(cleanPath,"/config.html")==0||
                std::strcmp(cleanPath,"/dashboard")==0)  handleConfig(sn);
        else if(std::strcmp(cleanPath,"/logs")==0||
                std::strcmp(cleanPath,"/logs.html")==0)  handleLogs(sn);
        else if(std::strcmp(cleanPath,"/test")==0)        handleTestPage(sn);
        else if(std::strcmp(cleanPath,"/export")==0)      handleExport(sn);
        else if(std::strcmp(cleanPath,"/api/sensors")==0) handleApiSensors(sn);
        else if(std::strcmp(cleanPath,"/api/config")==0)  handleApiConfig(sn);
        else if(std::strcmp(cleanPath,"/api/test_payload")==0) handleApiTestPayload(sn);
        else if(std::strcmp(cleanPath,"/api/channels")==0)handleApiChannels(sn);
        else if(std::strcmp(cleanPath,"/api/web_mode")==0)handleApiWebMode(sn);
        else if(std::strcmp(cleanPath,"/api/test_result")==0)handleApiTestResult(sn);
        else if(std::strcmp(cleanPath,"/api/logs/export")==0)handleApiLogsExport(sn);
        else if(std::strncmp(cleanPath,"/api/logs",9)==0) handleApiLogs(sn,queryStr);
        else if(std::strcmp(cleanPath,"/api/sd-test")==0)  handleApiSdTest(sn);
        else if(std::strcmp(cleanPath,"/files")==0||
                std::strcmp(cleanPath,"/files.html")==0)         handleFiles(sn);
        else if(std::strcmp(cleanPath,"/test")==0||
                std::strcmp(cleanPath,"/test.html")==0)           serveFile(sn,"0:/www/test.html","text/html");
        else if(std::strncmp(cleanPath,"/api/files",10)==0)      handleApiFiles(sn,queryStr,request);
        else if(std::strncmp(cleanPath,"/api/download",13)==0)   handleApiDownload(sn,queryStr,request);
        else{
            const char* ext=std::strrchr(cleanPath,'.');
            const char* ct="text/plain";
            if(ext){
                if(std::strcmp(ext,".html")==0) ct="text/html";
                else if(std::strcmp(ext,".css")==0) ct="text/css";
                else if(std::strcmp(ext,".js")==0)  ct="application/javascript";
                else if(std::strcmp(ext,".json")==0)ct="application/json";
            }
            if(!serveFile(sn,cleanPath,ct)) send404(sn);
        }
    }
    else if(std::strcmp(method,"POST")==0){
        const char* body=std::strstr(request,"\r\n\r\n");
        if(body) body+=4;
        if(std::strcmp(cleanPath,"/config")==0||
           std::strcmp(cleanPath,"/api/config")==0) handlePostConfig(sn,body);
        else if(std::strcmp(cleanPath,"/api/settime")==0)    handleApiSetTime(sn,body);
        else if(std::strcmp(cleanPath,"/api/test_send")==0)  handleApiTestSend(sn,queryStr);
        else if(std::strcmp(cleanPath,"/api/logs/clear")==0) handleApiLogsClear(sn);
    else if(std::strcmp(cleanPath,"/api/backup/download")==0) handleApiBackupDownload(sn);
        else if(std::strcmp(cleanPath,"/api/upload")==0)  handleApiUpload(sn,body,request);
        else if(std::strcmp(cleanPath,"/api/delete")==0)  handleApiDelete(sn,queryStr);
        else send404(sn);
    }
    else send404(sn);
}


// ── File Manager API ─────────────────────────────────────────────────────────

// Вспомогательная: извлечь значение параметра из query-string
// Пример: queryStr="path=0%3A%2Flogs&x=1", key="path" → "0:/logs"
static void urlDecode(const char* src, char* dst, size_t dstSz){
    size_t o=0;
    while(*src && o<dstSz-1){
        if(*src=='%' && src[1] && src[2]){
            char hex[3]={src[1],src[2],0};
            dst[o++]=(char)std::strtol(hex,nullptr,16);
            src+=3;
        } else if(*src=='+'){
            dst[o++]=' '; src++;
        } else {
            dst[o++]=*src++;
        }
    }
    dst[o]='\0';
}

static bool getQueryParam(const char* qs, const char* key, char* out, size_t outSz){
    size_t klen=std::strlen(key);
    const char* p=qs;
    while(p && *p){
        if(std::strncmp(p,key,klen)==0 && p[klen]=='='){
            const char* v=p+klen+1;
            const char* e=std::strchr(v,'&');
            size_t vlen=e?(size_t)(e-v):std::strlen(v);
            if(vlen>=outSz) vlen=outSz-1;
            std::strncpy(out,v,vlen); out[vlen]='\0';
            urlDecode(out,out,outSz);
            return true;
        }
        p=std::strchr(p,'&');
        if(p) p++;
    }
    return false;
}

// GET /files — отдаём files.html с SD или встроенный минимальный UI
void WebServer::handleFiles(uint8_t sn){
    if(serveFile(sn,"/files.html","text/html")) return;
    // Встроенный минимальный fallback
    const char* html=
        "<!DOCTYPE html><html><head><meta charset='utf-8'>"
        "<title>Files — MonSet</title></head><body>"
        "<h2>File Manager</h2>"
        "<p>files.html not found on SD. Place files.html at 0:/files.html</p>"
        "<a href='/'>← Back</a></body></html>";
    sendResponse(sn,200,"text/html",html,(uint16_t)std::strlen(html));
}

// GET /api/files?path=0:/  — JSON список файлов/папок
void WebServer::handleApiFiles(uint8_t sn, const char* queryStr, const char* /*request*/){
    char dirPath[64]="0:/";
    getQueryParam(queryStr,"path",dirPath,sizeof(dirPath));
    // FatFS не принимает "/" как корень — маппируем на "0:/"
    if(std::strcmp(dirPath,"/")==0 || dirPath[0]=='\0') std::strncpy(dirPath,"0:/",sizeof(dirPath));

    char resp[4096]; int n=0;
    n+=std::snprintf(resp+n,sizeof(resp)-n,"{\"path\":\"%s\",\"items\":[",dirPath);

    DIR dir; FILINFO fno;
    FRESULT fr=f_opendir(&dir,dirPath);
    if(fr!=FR_OK){
        std::snprintf(resp,sizeof(resp),"{\"error\":\"opendir failed fr=%d\"}",(int)fr);
        sendResponse(sn,200,"application/json",resp,(uint16_t)std::strlen(resp));
        return;
    }
    bool first=true;
    while(f_readdir(&dir,&fno)==FR_OK && fno.fname[0]){
        if(!first) n+=std::snprintf(resp+n,sizeof(resp)-n,",");
        first=false;
        bool isDir=(fno.fattrib & AM_DIR)!=0;
        n+=std::snprintf(resp+n,sizeof(resp)-n,
            "{\"name\":\"%s\",\"size\":%lu,\"dir\":%s}",
            fno.fname,(unsigned long)fno.fsize, isDir?"true":"false");
        if(n>(int)sizeof(resp)-128) break; // защита от переполнения
    }
    f_closedir(&dir);
    n+=std::snprintf(resp+n,sizeof(resp)-n,"]}");
    sendResponse(sn,200,"application/json",resp,(uint16_t)n);
}

// GET /api/download?path=0:/file.txt — отдаём файл с SD побайтово
void WebServer::handleApiDownload(uint8_t sn, const char* queryStr, const char* /*request*/){
    char filePath[128]="";
    if(!getQueryParam(queryStr,"path",filePath,sizeof(filePath))||!filePath[0]){
        const char* e="{\"error\":\"no path\"}";
        sendResponse(sn,400,"application/json",e,(uint16_t)std::strlen(e)); return;
    }

    FIL f; FRESULT fr=f_open(&f,filePath,FA_READ);
    if(fr!=FR_OK){
        char e[64]; std::snprintf(e,sizeof(e),"{\"error\":\"open failed fr=%d\"}",(int)fr);
        sendResponse(sn,404,"application/json",e,(uint16_t)std::strlen(e)); return;
    }

    // Имя файла для Content-Disposition
    const char* slash=std::strrchr(filePath,'/');
    const char* fname=slash?(slash+1):filePath;

    // Заголовок
    char hdr[256];
    int hl=std::snprintf(hdr,sizeof(hdr),
        "HTTP/1.1 200 OK\r\n"
        "Content-Type: application/octet-stream\r\n"
        "Content-Disposition: attachment; filename=\"%s\"\r\n"
        "Connection: close\r\n\r\n", fname);
    send(sn,(uint8_t*)hdr,(uint16_t)hl);

    // Стриминг чанками
    static uint8_t chunk[1024];
    UINT br=0;
    while(f_read(&f,chunk,sizeof(chunk),&br)==FR_OK && br>0){
        uint32_t sent=0;
        while(sent<br){
            int32_t r=send(sn,chunk+sent,(uint16_t)(br-sent));
            if(r<=0) break;
            sent+=(uint32_t)r;
        }
    }
    f_close(&f);
}

// POST /api/upload?path=0:/filename.txt  body=raw bytes
void WebServer::handleApiUpload(uint8_t sn, const char* body, const char* request){
    char filePath[128]="";
    // Извлекаем path из строки запроса (не из тела)
    char method[8]{}, urlBuf[128]{};
    std::sscanf(request,"%7s %127s",method,urlBuf);
    const char* qs=std::strchr(urlBuf,'?');
    if(qs) qs++;
    if(!qs||!getQueryParam(qs,"path",filePath,sizeof(filePath))||!filePath[0]){
        const char* e="{\"error\":\"no path in query\"}";
        sendResponse(sn,400,"application/json",e,(uint16_t)std::strlen(e)); return;
    }

    // Длина тела из Content-Length
    const char* clHdr=std::strstr(request,"Content-Length: ");
    int bodyLen=0;
    if(clHdr) bodyLen=std::atoi(clHdr+16);
    if(!body||bodyLen<=0){
        const char* e="{\"error\":\"empty body\"}";
        sendResponse(sn,400,"application/json",e,(uint16_t)std::strlen(e)); return;
    }

    FIL f; FRESULT fr=f_open(&f,filePath,FA_CREATE_ALWAYS|FA_WRITE);
    if(fr!=FR_OK){
        char e[64]; std::snprintf(e,sizeof(e),"{\"error\":\"create failed fr=%d\"}",(int)fr);
        sendResponse(sn,500,"application/json",e,(uint16_t)std::strlen(e)); return;
    }
    UINT bw=0;
    fr=f_write(&f,(const void*)body,(UINT)bodyLen,&bw);
    f_close(&f);
    if(fr!=FR_OK||bw==0){
        char e[64]; std::snprintf(e,sizeof(e),"{\"error\":\"write failed fr=%d bw=%u\"}",(int)fr,(unsigned)bw);
        sendResponse(sn,500,"application/json",e,(uint16_t)std::strlen(e)); return;
    }
    char ok[64]; std::snprintf(ok,sizeof(ok),"{\"status\":\"ok\",\"bytes\":%u}",(unsigned)bw);
    sendResponse(sn,200,"application/json",ok,(uint16_t)std::strlen(ok));
    DBG.info("WebServer: upload %s (%u bytes)",filePath,(unsigned)bw);
}

// POST /api/delete?path=0:/file.txt
void WebServer::handleApiDelete(uint8_t sn, const char* queryStr){
    char filePath[128]="";
    if(!getQueryParam(queryStr,"path",filePath,sizeof(filePath))||!filePath[0]){
        const char* e="{\"error\":\"no path\"}";
        sendResponse(sn,400,"application/json",e,(uint16_t)std::strlen(e)); return;
    }
    FRESULT fr=f_unlink(filePath);
    if(fr!=FR_OK){
        char e[64]; std::snprintf(e,sizeof(e),"{\"error\":\"unlink failed fr=%d\"}",(int)fr);
        sendResponse(sn,500,"application/json",e,(uint16_t)std::strlen(e)); return;
    }
    const char* ok="{\"status\":\"ok\"}";
    sendResponse(sn,200,"application/json",ok,(uint16_t)std::strlen(ok));
    DBG.info("WebServer: deleted %s",filePath);
}

// ── tick ──────────────────────────────────────────────────────────────────────
void WebServer::tick(){
    if(!m_running) return;
    uint8_t status=getSn_SR(HTTP_SOCKET);
    switch(status){
        case SOCK_ESTABLISHED:{
            int32_t len=getSn_RX_RSR(HTTP_SOCKET);
            if(len>0){
                if(!g_web_exclusive){
                    g_web_exclusive=true;
                    DBG.info("WebServer: WEB EXCLUSIVE MODE ON");
                    closeDataSockets(HTTP_SOCKET);
                }

                // Limit first read to buffer size
                if(len > REQ_BUF_SIZE - 1) len = REQ_BUF_SIZE - 1;
                int32_t rx = recv(HTTP_SOCKET, (uint8_t*)m_reqBuf, (uint16_t)len);

                if(rx > 0){
                    m_reqBuf[rx] = 0;

                    // If POST, check Content-Length and wait for the rest of the body
                    if (std::strncmp(m_reqBuf, "POST", 4) == 0) {
                        const char* clStr = std::strstr(m_reqBuf, "Content-Length: ");
                        if (clStr) {
                            int cl = std::atoi(clStr + 16);
                            if (cl <= 0) {
                                const char* r = "{\"error\":\"bad Content-Length\"}";
                                sendResponse(HTTP_SOCKET, 400, "application/json", r, (uint16_t)std::strlen(r));
                                disconnect(HTTP_SOCKET);
                                return;
                            }
                            if (cl >= REQ_BUF_SIZE - 1024) {
                                const char* r = "{\"error\":\"config payload too large\"}";
                                sendResponse(HTTP_SOCKET, 413, "application/json", r, (uint16_t)std::strlen(r));
                                DBG.error("WebServer: POST too large cl=%d", cl);
                                disconnect(HTTP_SOCKET);
                                return;
                            }
                            const char* bodyStart = std::strstr(m_reqBuf, "\r\n\r\n");
                            if (bodyStart) {
                                bodyStart += 4; // Skip CRLFCRLF
                                int currentBodyLen = rx - (bodyStart - m_reqBuf);

                                // Read the remaining bytes if any
                                uint32_t startWait = HAL_GetTick();
                                while (currentBodyLen < cl && (HAL_GetTick() - startWait) < 2000) {
                                    int32_t avail = getSn_RX_RSR(HTTP_SOCKET);
                                    if (avail > 0) {
                                        int toRead = cl - currentBodyLen;
                                        if (toRead > avail) toRead = avail;
                                        if (rx + toRead > REQ_BUF_SIZE - 1) toRead = REQ_BUF_SIZE - 1 - rx;
                                        if (toRead <= 0) break; // Safety against overflow

                                        int32_t chunk = recv(HTTP_SOCKET, (uint8_t*)(m_reqBuf + rx), (uint16_t)toRead);
                                        if (chunk > 0) {
                                            rx += chunk;
                                            m_reqBuf[rx] = 0;
                                            currentBodyLen += chunk;
                                            startWait = HAL_GetTick(); // Reset timeout
                                        }
                                    }
                                    IWDG->KR = 0xAAAA;
                                    HAL_Delay(1);
                                }
                            }
                        }
                    }

                    // Now process the fully assembled request
                    handleRequest(HTTP_SOCKET, m_reqBuf, (uint16_t)rx);
                }

                // Wait for TX buffer to drain before closing socket
                { uint32_t t0=HAL_GetTick();
                  uint16_t txmax=getSn_TxMAX(HTTP_SOCKET);
                  while(getSn_TX_FSR(HTTP_SOCKET)<txmax &&
                        (HAL_GetTick()-t0)<5000){ IWDG->KR=0xAAAA; HAL_Delay(2); }
                }
                disconnect(HTTP_SOCKET);
            }
            break;
        }
        case SOCK_CLOSE_WAIT: disconnect(HTTP_SOCKET); break;
        case SOCK_CLOSED:
            if(socket(HTTP_SOCKET,Sn_MR_TCP,HTTP_PORT,0)==HTTP_SOCKET) listen(HTTP_SOCKET);
            break;
        case SOCK_LISTEN: break;
        // W5500 промежуточные состояния TCP teardown:
        // 0x18=FIN_WAIT, 0x1A=CLOSING, 0x1B=TIME_WAIT — принудительно сбрасываем сокет
        // чтобы браузер мог подключиться снова без ожидания таймаута
        case 0x18: // SOCK_FIN_WAIT
        case 0x1A: // SOCK_CLOSING
        case 0x1B: // SOCK_TIME_WAIT
            close(HTTP_SOCKET);
            if(socket(HTTP_SOCKET,Sn_MR_TCP,HTTP_PORT,0)==HTTP_SOCKET) listen(HTTP_SOCKET);
            break;
        default: break;
    }
}